begin;
create table public.cbg_notification_deliveries(id bigint generated always as identity primary key,notification_id uuid unique not null references public.cbg_notifications(id) on delete cascade,channel text not null default 'email' check(channel='email'),recipient text not null,status text not null default 'pending' check(status in('pending','sending','sent','failed','cancelled')),attempt_count integer not null default 0 check(attempt_count>=0),next_attempt_at timestamptz not null default now(),provider_message_id text,safe_error text,created_at timestamptz not null default now(),sent_at timestamptz);
create index cbg_notification_delivery_queue_idx on public.cbg_notification_deliveries(status,next_attempt_at) where status in('pending','failed');alter table public.cbg_notification_deliveries enable row level security;
create policy cbg_notification_deliveries_admin_read on public.cbg_notification_deliveries for select to authenticated using(private.cbg_has_role('admin'));grant select on public.cbg_notification_deliveries to authenticated;grant usage,select on sequence public.cbg_notification_deliveries_id_seq to authenticated;
create function private.cbg_queue_notification_delivery() returns trigger language plpgsql security definer set search_path='' as $$declare target_email text;begin select email into target_email from public.cbg_users where id=new.user_id and active=true;if target_email is not null then insert into public.cbg_notification_deliveries(notification_id,recipient) values(new.id,target_email) on conflict(notification_id) do nothing;end if;return new;end$$;
revoke all on function private.cbg_queue_notification_delivery() from public,anon,authenticated;create trigger cbg_queue_notification_delivery after insert on public.cbg_notifications for each row execute function private.cbg_queue_notification_delivery();
commit;
